<script setup lang="ts">
import ReadRecoveryActions from '../components/ReadRecoveryActions.vue'
import {computed,nextTick,onUnmounted,ref,shallowRef,watch} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {feedback} from '../utils/feedback'
import {api} from '../api/client'
import {can,contextGeneration,session,switchingTenant} from '../stores/session'
import {contextTransitionGuards} from '../utils/contextTransitionGuard'
import {createReportWorkspace,emptyReportState} from '../utils/inspectionQuarterlyReportWorkspace'
import {createSourceCollectionWorkspace,emptySourceCollectionState} from '../utils/inspectionSourceCollectionWorkspace'
import {inspectionUuid} from '../utils/inspectionTemplates'
import {readReportPayload,pendingReportConfiguration,type ReportContext,type ReportConfiguration} from '../utils/inspectionQuarterlyReports'
import {fetchReportPdf,downloadReportPdf} from '../utils/inspectionReportPdf'
import {renderReportPreview,downloadReportPreview} from '../utils/inspectionReportPreview'
import {readReportDetail} from '../utils/inspectionQuarterlyReports'
import {displayTime} from '../utils/display'
import {frozenReportSources} from '../utils/inspectionReportDocument'
import InspectionWorksheetFacts from '../components/InspectionWorksheetFacts.vue'
import ApiErrorNotice from '../components/ApiErrorNotice.vue'
const state=shallowRef(emptyReportState()),workspace=createReportWorkspace(api,v=>{state.value=v})
const sourceState=shallowRef(emptySourceCollectionState()),sourceReader=createSourceCollectionWorkspace(api,v=>{sourceState.value=v})
const label=ref(''),year=ref(''),quarter=ref(''),sourceId=ref(''),configuration=ref(pendingReportConfiguration()),validation=ref(''),rowPage=ref(0),expanded=ref(''),sourceExpanded=ref('')
const permitted=computed(()=>Boolean(session.value?.mode==='remote_test'&&session.value.user.role==='padmin'&&can('inspection_quarterly_reports:read')&&!switchingTenant.value))
const writable=computed(()=>permitted.value&&can('inspection_quarterly_reports:write')&&can('inspection_source_collections:read'))
const contextKey=computed(()=>JSON.stringify([contextGeneration.value,session.value?.tenant.id,session.value?.user.id,session.value?.permission_version,session.value?.account_version,session.value?.user.role,permitted.value,writable.value]))
function context():ReportContext|null{const s=session.value;return s&&permitted.value?{tenantId:s.tenant.id,actorId:s.user.id,permissionVersion:s.permission_version,role:s.user.role,canRead:true,canWrite:writable.value}:null}
const previewButton=ref<HTMLButtonElement|null>(null),pdfButton=ref<HTMLButtonElement|null>(null),previewMode=ref<'html'|'pdf'>('html')
const previewBusy=ref(false),previewError=ref(''),previewStatus=ref('')
let disposed=false,previewAbort:AbortController|null=null,previewTurn=0
function cancelPreview(){previewTurn++;previewAbort?.abort();previewAbort=null;previewBusy.value=false;previewError.value='';previewStatus.value=''}
watch(()=>[contextKey.value,state.value.selected?.id,state.value.selected?.document_sha256],cancelPreview,{flush:'sync'})
async function cancelPreviewByUser(){if(!previewBusy.value)return;cancelPreview();const turn=previewTurn,key=contextKey.value;previewStatus.value='已取消，本次未发起下载。';await nextTick();if(turn!==previewTurn||key!==contextKey.value)return;(previewMode.value==='pdf'?pdfButton:previewButton).value?.focus()}
async function downloadPreview(){
 const selected=state.value.selected,scope=context()
 if(!selected||!scope||previewBusy.value||state.value.busy)return false
 previewMode.value='html'
 const id=selected.id,expectedHash=selected.document_sha256,turn=++previewTurn,controller=new AbortController();previewAbort=controller;previewBusy.value=true;previewError.value='';previewStatus.value=''
 const current=()=>turn===previewTurn&&!controller.signal.aborted&&permitted.value&&state.value.selected?.id===id&&state.value.selected.document_sha256===expectedHash
 try{
  const raw=await api.request('/inspection-quarterly-reports/'+id,{signal:controller.signal});if(!current())return false
  const verified=await readReportDetail(raw,scope,id,current);if(!current())return false
  if(verified.document_sha256!==expectedHash)throw new Error('冻结文档摘要已变化，停止下载，请重新读取报告。')
  const html=renderReportPreview(verified);if(!current())return false
  downloadReportPreview(html,id);previewStatus.value='已发起 HTML 草稿下载，请检查浏览器下载记录；不代表正式发布或文件已保存。';return true
 }catch(error){if(current())previewError.value=error instanceof Error?error.message:'预览生成失败，请手动重试';return false}
 finally{if(turn===previewTurn){previewBusy.value=false;previewAbort=null}}
}
async function downloadPdfPreview(){
 const selected=state.value.selected,scope=context();if(!selected||!scope||previewBusy.value||state.value.busy)return false
 previewMode.value='pdf';const id=selected.id,hash=selected.document_sha256,key=contextKey.value,turn=++previewTurn,controller=new AbortController();previewAbort=controller;previewBusy.value=true;previewError.value='';previewStatus.value=''
 const current=()=>turn===previewTurn&&!controller.signal.aborted&&key===contextKey.value&&permitted.value&&state.value.selected?.id===id&&state.value.selected.document_sha256===hash
 try{const file=await fetchReportPdf({id,tenantId:scope.tenantId,documentHash:hash,signal:controller.signal,active:current,onUnauthorized:()=>api.onUnauthorized()});if(!current())return false;downloadReportPdf(file);previewStatus.value=`已发起 ${file.pages} 页 PDF 草稿下载，请检查浏览器记录；不代表已保存、批准或发布。`;return true}
 catch(error){if(current())previewError.value=error instanceof Error?error.message:'PDF 草稿未下载，请手动重试或使用 HTML 预览';return false}
 finally{if(turn===previewTurn){previewBusy.value=false;previewAbort=null}}
}
const locked=computed(()=>!writable.value||Boolean(state.value.busy)||Boolean(state.value.attempt)||Boolean(sourceState.value.busy))
const dirty=computed(()=>state.value.attempt?.state!=='accepted'&&(label.value!==''||year.value!==''||quarter.value!==''||sourceId.value!==''||Object.values(configuration.value).some(v=>v!==null)||state.value.attempt?.state==='rejected'))
const frozenSources=computed(()=>new Map((state.value.selected?frozenReportSources(state.value.selected.frozen_document):[]).map(s=>[s.worksheet_id+'/'+s.version,s])))
const detailRows=computed(()=>state.value.selected?.frozen_document.output.rows.slice(rowPage.value*10,rowPage.value*10+10)??[])
const configFields=[['revision','配置修订标识'],['time_zone','报告业务时区'],['metric_version','指标版本'],['report_template_version','报告模板版本']] as const
function setText(key:keyof ReportConfiguration,event:Event){if(locked.value)return;const value=(event.target as HTMLInputElement).value;configuration.value={...configuration.value,[key]:value===''?null:value}}
function resetSource(){sourceReader.reset(writable.value?{...context()!,canWrite:false}:null)}
watch(sourceId,resetSource,{flush:'sync'})
function clearForm(){label.value='';year.value='';quarter.value='';sourceId.value='';configuration.value=pendingReportConfiguration();validation.value='';resetSource()}
watch(contextKey,()=>{workspace.reset(context());clearForm();rowPage.value=0;expanded.value='';sourceExpanded.value='';if(permitted.value)void workspace.list()},{immediate:true,flush:'sync'})
async function readSource(){if(locked.value)return false;validation.value='';if(!inspectionUuid(sourceId.value)){validation.value='请输入规范小写来源集合 UUID，不自动选择最新集合';return false}return sourceReader.select(sourceId.value)}
function payload(){const s=sourceState.value.selected;if(!s||s.id!==sourceId.value||!/^([1-9][0-9]{0,3})$/.test(year.value)||! /^[1-4]$/.test(quarter.value))throw new Error('invalid explicit inputs');return readReportPayload({expected_version:0,label:label.value,source_collection_id:s.id,expected_source_document_sha256:s.document_sha256,expected_source_manifest_sha256:s.source_manifest_sha256,year:Number(year.value),quarter:Number(quarter.value),configuration:{...configuration.value}})}
async function save(){if(locked.value)return false;validation.value='';let p;try{p=payload()}catch{validation.value='核对来源集合后，填写非空标签、1–9998年和1–4季度；所有待确认配置保持空值。';return false}const turn=contextKey.value,ok=await workspace.submit(p);if(ok&&turn===contextKey.value)feedback.success('原季度草稿保存回执已确认，冻结输入输出请单独回读');return ok}
async function retry(){return workspace.retry()}
function unlockRejected(){if(state.value.attempt?.state!=='rejected'||!workspace.begin())return false;validation.value='原请求已拒绝；保留明确来源与配置，修改后手动保存';return true}
function formSnapshot(){const source=sourceState.value.selected;return JSON.stringify([label.value,year.value,quarter.value,sourceId.value,configuration.value,source?[source.id,source.document_sha256,source.source_manifest_sha256]:null])}
async function discard(){const turn=contextKey.value,input=formSnapshot();if(dirty.value){try{await ElMessageBox.confirm('清除未保存的期次、配置与来源集合选择？已保存报告不会改变。','保留季度草稿输入',{confirmButtonText:'清除未保存输入',cancelButtonText:'保留输入',type:'warning'})}catch{return false}}else await Promise.resolve();return !disposed&&turn===contextKey.value&&input===formSnapshot()&&!workspace.unresolved()}
async function begin(){if(disposed||workspace.unresolved()||state.value.busy||sourceState.value.busy)return false;const turn=contextKey.value,input=formSnapshot();if(!await discard()||disposed||turn!==contextKey.value||input!==formSnapshot()||sourceState.value.busy||!writable.value||!workspace.begin())return false;clearForm();return true}
async function select(id:string){rowPage.value=0;expanded.value='';sourceExpanded.value='';return workspace.select(id)}
async function browse(next=false){rowPage.value=0;expanded.value='';sourceExpanded.value='';return workspace.list(next)}
async function mayLeave(){if(workspace.unresolved()){feedback.warning('先用完全相同原请求恢复结果；列表刷新不能确认是否已保存');return false}const turn=contextKey.value,input=formSnapshot();return await discard()&&!disposed&&turn===contextKey.value&&input===formSnapshot()&&!workspace.unresolved()}
onBeforeRouteLeave(mayLeave);const unregister=contextTransitionGuards.register(mayLeave)
function beforeUnload(event:BeforeUnloadEvent){if(workspace.unresolved()||dirty.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload)
onUnmounted(()=>{disposed=true;cancelPreview();unregister();workspace.dispose();sourceReader.dispose();window.removeEventListener('beforeunload',beforeUnload)})
defineExpose({downloadPreview,downloadPdfPreview,cancelPreview,previewBusy,previewError,previewStatus,state,sourceState,label,year,quarter,sourceId,configuration,validation,save,retry,begin,unlockRejected,readSource,payload,select,browse,hasUnresolved:workspace.unresolved})
</script>
<template>
<section class="quarterly-report-page">
 <div class="page-heading"><div><h1>季度巡检报告草稿</h1><p>当前租户：{{ session?.tenant.name }} · 冻结输入与输出 · 历史不重算</p></div></div>
 <el-alert type="warning" :closable="false" title="仅保存 DRAFT，不代表客户批准、正式执行或发布">配置来源 REQUEST_DRAFT_NOT_APPROVED。空配置仍为 null，不借用平台时区或默认选取规则。来源完整性仅指明确集合，租户资产总量未知，不计算覆盖率，不授予附件访问。</el-alert>
 <p v-if="!permitted" class="empty-panel">当前身份没有真实测试环境季度报告读取权限</p>
 <template v-else>
 <nav class="feature-tabs" aria-label="巡检工作区"><router-link to="/inspection-templates">模板候选</router-link><router-link to="/inspection-worksheets">执行单</router-link><router-link to="/inspection-source-collections">来源集合</router-link><span class="active">季度草稿</span></nav>
 <ApiErrorNotice :error="state.error" /><ReadRecoveryActions :busy="state.busy" :can-retry="workspace.canRetryRead()" :scope-key="contextKey" :cancel="workspace.cancelRead" :retry="workspace.retryRead" />
 <p v-if="state.busy" role="status">{{ state.busy==='write'?'正在提交固定原请求…':'正在读取冻结记录…' }}</p>
 <section v-if="state.attempt" class="panel original-request" aria-live="polite"><h2>固定原请求</h2><p v-if="state.attempt.state==='uncertain'">结果未知。仅重放相同请求和幂等键；列表和详情读取不能确认本次写入，重试拒绝也不能证明之前没有保存。</p><p v-else-if="state.attempt.state==='accepted'">原保存回执已核对，元数据不代表完整冻结正文已核对。</p><p v-else>原请求已拒绝，原输入保留；解锁后手动修改，不自动更换来源。</p><div class="actions"><button v-if="state.attempt.state==='uncertain'" :disabled="Boolean(state.busy)" @click="retry">恢复原请求</button><button v-if="state.attempt.state==='rejected'" :disabled="Boolean(state.busy)" @click="unlockRejected">保留输入并解锁</button><button v-if="state.receipt" :disabled="Boolean(state.busy)" @click="select(state.receipt.id)">回读已保存冻结报告</button><button v-if="state.attempt.state==='accepted'&&writable" :disabled="Boolean(state.busy)" @click="begin">新建另一份季度草稿</button></div></section>
 <section class="panel report-list"><div class="heading-row"><h2>已保存季度草稿 · 仅元数据</h2><button :disabled="Boolean(state.busy)" @click="browse()">刷新列表</button></div><p>刷新不提交新报告，不解除未知写入，不重新汇总当前来源。</p><p v-if="!state.page" class="empty-panel">{{ state.busy==='read'?'正在读取，数量未知':state.error?'读取失败，旧列表不作成功结果':'尚未读取' }}</p><template v-else><div class="table-scroll" tabindex="0" role="region" aria-label="季度报告列表，可横向滚动"><table><thead><tr><th>报告标签</th><th>期次</th><th>记录时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in state.page.items" :key="r.id"><td>{{r.label}}<small class="hash">{{r.id}}</small></td><td>{{r.year}} Q{{r.quarter}}</td><td>{{displayTime(r.recorded_at)}}</td><td>DRAFT · 未发布<small>正文未读取</small></td><td><button :disabled="Boolean(state.busy)" @click="select(r.id)">读取冻结报告</button></td></tr></tbody></table></div><p v-if="!state.page.items.length">当前页没有报告，不代表没有资产或巡检完成。</p><div class="actions"><button v-if="state.paged" :disabled="Boolean(state.busy)" @click="browse()">返回第一页</button><button :disabled="Boolean(state.busy)||!state.page.has_more" @click="browse(true)">下一页</button></div></template></section>
 <section v-if="state.selected" class="panel report-detail"><h2>{{state.selected.label}} · {{state.selected.year}} Q{{state.selected.quarter}}</h2><p>冻结文档、来源、模板、执行单与报告输入摘要已核对。以下为已保存输出；没有重读当前头部或重算历史。</p><p class="warning">DRAFT · 配置未批准 · 不可发布 · 未发布 · 来源人工自述未核验 · 租户总资产未知</p>
  <div class="actions"><button ref="previewButton" :disabled="previewBusy||Boolean(state.busy)" @click="downloadPreview">下载 HTML 草稿预览</button><button ref="pdfButton" :disabled="previewBusy||Boolean(state.busy)" @click="downloadPdfPreview">下载 PDF 草稿预览</button><button v-if="previewBusy" @click="cancelPreviewByUser">取消预览下载</button></div><p>下载前重新验证权限及冻结内容。文件含租户数据，请妥善保存；离线副本无法随权限撤销而收回。仅预览全部资产输出与摘要，不含完整来源原文和附件。PDF 同样是未批准草稿，并非正式报告；需配置匹配摘要的本地字体，缺字或版面异常会拒绝生成。PDF 技术上限为 200 页、200,000 文字字符与 8 MiB，未通过 PDF/UA 或屏幕阅读器验收。</p><p v-if="previewBusy" role="status">正在重新核对并生成预览…</p><p v-if="previewStatus" role="status">{{previewStatus}}</p><p v-if="previewError" role="alert">{{previewError}}</p>
  <details open><summary>冻结配置与来源</summary><dl class="facts"><div v-for="(v,k) in state.selected.frozen_document.configuration" :key="k"><dt>{{k}}</dt><dd>{{v===null?'未配置（null）':v}}</dd></div></dl><p class="hash">来源集合：{{state.selected.source_collection_id}}</p><p class="hash">来源文档 SHA256：{{state.selected.source_document_sha256}}</p><p class="hash">来源清单 SHA256：{{state.selected.source_manifest_sha256}}</p><p class="hash">报告输入 SHA256：{{state.selected.report_sha256}}</p><p class="hash">冻结文档 SHA256：{{state.selected.document_sha256}}</p></details>
  <h3>已选来源汇总（非租户覆盖率）</h3><dl class="facts"><div><dt>捕获资产</dt><dd>{{state.selected.frozen_document.output.summary.capturedAssets}}</dd></div><div><dt>选定资产</dt><dd>{{state.selected.frozen_document.output.summary.selectedAssets}}</dd></div><div><dt>待解决选取</dt><dd>{{state.selected.frozen_document.output.summary.unresolvedAssets}}</dd></div><div><dt>检查项</dt><dd>{{state.selected.frozen_document.output.summary.totalItems}}</dd></div><div><dt>正常</dt><dd>{{state.selected.frozen_document.output.summary.normal}}</dd></div><div><dt>建议关注</dt><dd>{{state.selected.frozen_document.output.summary.attention}}</dd></div><div><dt>需处理</dt><dd>{{state.selected.frozen_document.output.summary.requiresAction}}</dd></div><div><dt>未填写</dt><dd>{{state.selected.frozen_document.output.summary.unanswered}}</dd></div></dl>
  <h3>待解决事项</h3><ul><li v-for="r in state.selected.frozen_document.output.pending_reasons" :key="r">{{r}}</li></ul>
  <h3>按资产核对冻结结果</h3><article v-for="row in detailRows" :key="row.asset_id" class="frozen-row"><h4>{{row.asset_name??'未选定来源'}} · {{row.status}}</h4><p class="hash">{{row.asset_id}}</p><p>捕获 {{row.candidates.length}} 个修订；{{row.selected?'已明确选取一个冻结修订':'未选定，不计作正常'}}</p><button :aria-expanded="expanded===row.asset_id" @click="expanded=expanded===row.asset_id?'':row.asset_id">{{expanded===row.asset_id?'收起明细':'展开明细'}}</button><template v-if="expanded===row.asset_id"><article v-for="candidate in row.candidates" :key="candidate.worksheetId+'/'+candidate.version" class="frozen-candidate"><p class="hash">{{candidate.worksheetId}} · v{{candidate.version}} · {{candidate.snapshotSha256}}</p><button :aria-expanded="sourceExpanded===candidate.worksheetId+'/'+candidate.version" @click="sourceExpanded=sourceExpanded===candidate.worksheetId+'/'+candidate.version?'':candidate.worksheetId+'/'+candidate.version">{{sourceExpanded===candidate.worksheetId+'/'+candidate.version?'收起冻结来源':'查看冻结来源原文'}}</button><InspectionWorksheetFacts v-if="sourceExpanded===candidate.worksheetId+'/'+candidate.version" :value="frozenSources.get(candidate.worksheetId+'/'+candidate.version)!" /></article><div v-for="item in row.items" :key="item.item.key" class="item"><strong>{{item.item.section}} · {{item.item.label}}</strong><p>{{item.item.instruction}}</p><p>{{item.observation?.result??'未填写'}} · {{item.observation?.note??'无备注'}}</p></div><p v-if="!row.items.length">没有选定检查项，不代表零项已完成。</p></template></article>
  <div class="actions"><button :disabled="rowPage===0" @click="rowPage--;expanded=''">上一组资产</button><span>本组 {{detailRows.length}} / 全部 {{state.selected.frozen_document.output.rows.length}}</span><button :disabled="(rowPage+1)*10>=state.selected.frozen_document.output.rows.length" @click="rowPage++;expanded=''">下一组资产</button></div>
  <p>异常明细：{{state.selected.frozen_document.output.findings.length}} 项（上方展开所选来源的关注及需处理项）；证据访问未授权。</p>
 </section>
 <details v-if="writable" class="panel report-editor" :open="dirty||Boolean(state.attempt)"><summary>＋ 新建不可变季度草稿</summary><p>先核对一份明确来源集合。已存报告不能编辑；新建不会替换旧报告。</p><ApiErrorNotice :error="sourceState.error" /><fieldset :disabled="locked"><label>来源集合 ID<input v-model="sourceId" aria-label="季度报告来源集合ID" autocomplete="off" /></label><button type="button" @click="readSource">读取并核对明确集合</button></fieldset><p v-if="sourceState.busy" role="status">正在核对完整来源集合…</p><section v-if="sourceState.selected" class="verified-source"><h3>{{sourceState.selected.label}}</h3><p>已核对 {{sourceState.selected.source_count}} 个冻结修订 · {{sourceState.selected.diagnostics.distinct_selected_assets}} 个已选资产，非租户总资产</p><p class="hash">文档 {{sourceState.selected.document_sha256}}</p><p v-if="sourceState.selected.source_count===0" class="warning">空集合只表示明确空选择，不表示零库存或全部完成。</p></section>
 <form v-form-feedback @submit.prevent="save"><fieldset :disabled="locked"><label>报告标签<input v-model="label" aria-label="季度报告标签" required autocomplete="off" /></label><div class="facts"><label>年（1–9998）<input v-model="year" aria-label="报告年" inputmode="numeric" required /></label><label>季度<select v-model="quarter" aria-label="报告季度" required><option value="">明确选择季度</option><option v-for="q in 4" :key="q" :value="String(q)">{{q}}</option></select></label></div><p>下列六项均为未批准请求配置。空白明确保存 null，不自动补默认值。</p><div class="facts"><label v-for="[key,title] in configFields" :key="key">{{title}}<input :value="configuration[key]??''" :aria-label="title" @input="setText(key,$event)" /></label><label>同资产多来源规则<select v-model="configuration.duplicate_rule" aria-label="同资产多来源规则"><option :value="null">未配置（null）</option><option value="REQUIRE_SINGLE_SOURCE">必须单一来源</option><option value="LATEST_REPORTED_PERFORMED_AT">选择最新自述时间（并列保持未解决）</option></select></label><label>归档来源规则<select v-model="configuration.archived_rule" aria-label="归档来源规则"><option :value="null">未配置（null）</option><option value="INCLUDE">包含</option><option value="EXCLUDE">排除</option></select></label></div><button class="primary-button" type="submit" :disabled="!sourceState.selected">保存季度 DRAFT</button></fieldset><p v-if="validation" role="alert" class="warning">{{validation}}</p></form><button v-if="!state.attempt" :disabled="Boolean(state.busy)||Boolean(sourceState.busy)" @click="begin">清除未保存输入</button></details>
 <p v-else class="empty-panel">缺少季度报告写入或来源集合读取权限，仅可查看已有报告。</p>
 </template>
</section>
